create extension if not exists pgcrypto;
create table if not exists public.cities(id uuid primary key default gen_random_uuid(),name text not null,state text not null,country text not null default 'Nigeria',slug text not null unique,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.vehicle_types(id text primary key,label text not null,min_capacity integer not null,max_capacity integer not null,sort_order integer not null default 0);
create table if not exists public.places(id uuid primary key default gen_random_uuid(),city_id uuid not null references public.cities(id) on delete cascade,name text not null,category text not null default 'other',aliases text[] not null default '{}',is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.stops(id uuid primary key default gen_random_uuid(),city_id uuid not null references public.cities(id) on delete cascade,name text not null,area text,landmark text,aliases text[] not null default '{}',latitude double precision,longitude double precision,is_active boolean not null default true,created_at timestamptz not null default now(),check((latitude is null and longitude is null) or (latitude between -90 and 90 and longitude between -180 and 180)));
create table if not exists public.place_stops(place_id uuid not null references public.places(id) on delete cascade,stop_id uuid not null references public.stops(id) on delete cascade,walking_minutes_min integer,walking_minutes_max integer,is_primary boolean not null default false,primary key(place_id,stop_id));
create table if not exists public.legs(id uuid primary key default gen_random_uuid(),city_id uuid not null references public.cities(id) on delete cascade,from_stop_id uuid not null references public.stops(id),to_stop_id uuid not null references public.stops(id),distance_km numeric(6,2),minutes_min integer,minutes_max integer,heading_label text,boarding_hint text,dropoff_hint text,landmarks text[] not null default '{}',is_active boolean not null default true,created_at timestamptz not null default now(),check(from_stop_id<>to_stop_id),check(minutes_min is null or minutes_min>=0),check(minutes_max is null or minutes_max>=coalesce(minutes_min,0)));
create index if not exists legs_from_idx on public.legs(city_id,from_stop_id) where is_active;
create index if not exists legs_to_idx on public.legs(city_id,to_stop_id) where is_active;
create table if not exists public.fares(id uuid primary key default gen_random_uuid(),leg_id uuid not null references public.legs(id) on delete cascade,vehicle_type_id text not null references public.vehicle_types(id),fare_type text not null default 'shared_seat' check(fare_type in ('shared_seat','charter')),amount_min numeric(10,2) not null,amount_max numeric(10,2) not null,currency text not null default 'NGN',last_confirmed_at timestamptz,approved_report_count integer not null default 0,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(amount_min>0 and amount_max>=amount_min),unique(leg_id,vehicle_type_id,fare_type));
create table if not exists public.reports(id uuid primary key default gen_random_uuid(),city_id uuid references public.cities(id) on delete set null,report_type text not null check(report_type in ('fare','route_issue','place_suggestion','stop_suggestion','leg_suggestion','trip_feedback')),leg_id uuid references public.legs(id) on delete set null,vehicle_type_id text references public.vehicle_types(id),fare_type text check(fare_type in ('shared_seat','charter')),amount numeric(10,2),place_name text,stop_name text,suggestion text,note text,status text not null default 'pending' check(status in ('pending','approved','rejected')),created_at timestamptz not null default now(),reviewed_at timestamptz,reviewed_by uuid,check(amount is null or amount>0));
create index if not exists reports_pending_idx on public.reports(created_at desc) where status='pending';
create index if not exists fares_leg_vehicle_idx on public.fares(leg_id,vehicle_type_id,fare_type) where is_active;
alter table public.cities enable row level security;
alter table public.vehicle_types enable row level security;
alter table public.places enable row level security;
alter table public.stops enable row level security;
alter table public.place_stops enable row level security;
alter table public.legs enable row level security;
alter table public.fares enable row level security;
alter table public.reports enable row level security;
create policy "Public can read active cities" on public.cities for select to anon,authenticated using(is_active);
create policy "Public can read vehicle types" on public.vehicle_types for select to anon,authenticated using(true);
create policy "Public can read active places" on public.places for select to anon,authenticated using(is_active);
create policy "Public can read active stops" on public.stops for select to anon,authenticated using(is_active);
create policy "Public can read place stop links" on public.place_stops for select to anon,authenticated using(true);
create policy "Public can read active legs" on public.legs for select to anon,authenticated using(is_active);
create policy "Public can read active fares" on public.fares for select to anon,authenticated using(is_active);
create policy "Public can submit pending reports" on public.reports for insert to anon,authenticated with check(status='pending');
create policy "Reports are private" on public.reports for select to anon,authenticated using(false);
grant select on public.cities,public.vehicle_types,public.places,public.stops,public.place_stops,public.legs,public.fares to anon,authenticated;
grant insert on public.reports to anon,authenticated;